package com.student.controller;
import com.student.dao.AdminDAO; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class AdminLoginServlet extends HttpServlet { private final AdminDAO dao=new AdminDAO(); protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(Auth.loggedIn(req)){resp.sendRedirect("dashboard");return;}req.getRequestDispatcher("/admin-login.jsp").forward(req,resp);} protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String u=req.getParameter("username"),p=req.getParameter("password");if(dao.authenticate(u,p)){HttpSession s=req.getSession(true);s.setAttribute("adminLoggedIn",true);s.setAttribute("adminName",dao.getName());s.setAttribute("adminUsername",u);resp.sendRedirect("dashboard");}else{req.setAttribute("error","Invalid username or password.");req.getRequestDispatcher("/admin-login.jsp").forward(req,resp);}}catch(Exception e){throw new ServletException(e);}}}
